Looking at this logic puzzle, I need to find who owns the rabbit by satisfying all 17 constraints. Let me write a Python program to solve this systematically.

```python
from itertools import permutations

people = ['Blake', 'Finley', 'Quinn', 'Riley', 'Sawyer']
colors = ['blue', 'orange', 'red', 'white', 'yellow']
pets = ['cat', 'dog', 'fish', 'horse', 'rabbit']
drinks = ['cocoa', 'coffee', 'juice', 'milk', 'water']
hobbies = ['chess', 'fencing', 'hiking', 'painting', 'rowing']

def check_solution(houses):
    """Check if a solution satisfies all constraints."""

    def find_pos(attr_type, attr_value):
        for i in range(5):
            if houses[i][attr_type] == attr_value:
                return i
        return -1

    # Clue 1: Coffee drinker lives next to blue house person
    if abs(find_pos('drink', 'coffee') - find_pos('color', 'blue')) != 1:
        return False

    # Clue 2: Fencing immediately left of fish owner
    if find_pos('pet', 'fish') != find_pos('hobby', 'fencing') + 1:
        return False

    # Clue 3: Hiking immediately left of Sawyer
    if find_pos('person', 'Sawyer') != find_pos('hobby', 'hiking') + 1:
        return False

    # Clue 4: Juice drinker is dog owner
    if find_pos('drink', 'juice') != find_pos('pet', 'dog'):
        return False

    # Clue 5: Orange house person drinks water
    if find_pos('color', 'orange') != find_pos('drink', 'water'):
        return False

    # Clue 6: Juice drinker is not in white house
    if houses[find_pos('drink', 'juice')]['color'] == 'white':
        return False

    # Clue 7: Horse owner lives next to Quinn
    if abs(find_pos('pet', 'horse') - find_pos('person', 'Quinn')) != 1:
        return False

    # Clue 8: Cocoa drinker immediately left of red house
    if find_pos('color', 'red') != find_pos('drink', 'cocoa') + 1:
        return False

    # Clue 9: White house person lives next to fish owner
    if abs(find_pos('color', 'white') - find_pos('pet', 'fish')) != 1:
        return False

    # Clue 10: Blake immediately left of red house
    if find_pos('color', 'red') != find_pos('person', 'Blake') + 1:
        return False

    # Clue 11: Milk drinker immediately left of rabbit owner
    if find_pos('pet', 'rabbit') != find_pos('drink', 'milk') + 1:
        return False

    # Clue 12: Sawyer lives next to white house
    if abs(find_pos('person', 'Sawyer') - find_pos('color', 'white')) != 1:
        return False

    # Clue 13: Finley is not in orange house
    if find_pos('person', 'Finley') == find_pos('color', 'orange'):
        return False

    # Clue 14: Painting hobbyist is fish owner
    if find_pos('hobby', 'painting') != find_pos('pet', 'fish'):
        return False

    # Clue 15: Water drinker is rabbit owner
    if find_pos('drink', 'water') != find_pos('pet', 'rabbit'):
        return False

    # Clue 16: Chess hobbyist is not Finley
    if find_pos('hobby', 'chess') == find_pos('person', 'Finley'):
        return False

    # Clue 17: Riley immediately left of rowing hobbyist
    if find_pos('hobby', 'rowing') != find_pos('person', 'Riley') + 1:
        return False

    return True

# Find solution
for person_perm in permutations(people):
    for color_perm in permutations(colors):
        for pet_perm in permutations(pets):
            for drink_perm in permutations(drinks):
                for hobby_perm in permutations(hobbies):
                    houses = {i: {
                        'person': person_perm[i],
                        'color': color_perm[i],
                        'pet': pet_perm[i],
                        'drink': drink_perm[i],
                        'hobby': hobby_perm[i]
                    } for i in range(5)}

                    if check_solution(houses):
                        # Find rabbit owner
                        for i in range(5):
                            if houses[i]['pet'] == 'rabbit':
                                print(houses[i]['person'])
                        exit()
```

ANSWER: Finley
